#include<limits.h>
#include <assert.h>

#define N 100000
#define fun mapavg

/* unknown() contract */
int unknown();

/*@
	requires 0 <= N < 0x80000000;
	assigns \nothing;
	ensures INT_MIN <= \result < INT_MAX;
*/

/* Logic function for sum */
/*
	logic integer sum_of(int *x, integer n) =
	n <= 0 ? 0 : sum_of(x, n-1) + x[n-1];
*/

/* mapavg contract */
int fun(int *x);

/*@
	requires N > 0;
	requires \valid_read(x+(0..N-1));
	requires INT_MIN <= x[0] < INT_MAX;
	assigns \nothing;
	ensures \result == (N*(N-1)/2 + sum_of(x,N))/N;
*/

int main(void) {
	int i;
	long long ret, ret2, ret5;
	int x[N];

	/* Fill the array with values in INT range */
	for(i=0; i<N; i++) {
		x[i] = unknown();
	}

	/* Loop invariant for fill */
	/*
	loop invariant 0 <= i <= N;
	loop invariant \forall integer j; 0 <= j < i ==> INT_MIN <= x[j] < INT_MAX;
	loop assigns i, x[0..N-1];
	loop variant N - i;
	*/

	/* After fill, ensure all x values in range */
	//@ assert \forall integer j; 0 <= j < N ==> INT_MIN <= x[j] < INT_MAX;

	ret = fun(x);
	ret2 = fun(x);
	ret5 = fun(x);

	/* Final assertion to prove all results are equal */
	assert !(ret != ret2 || ret != ret5);
}
